CREATE VIEW v AS SELECT CAST("location" AS VARCHAR) AS "location",CAST("extraction_request" AS VARCHAR) AS "extraction_request",CAST("buffer_radius_m" AS DOUBLE) AS "buffer_radius_m",CAST("extraction_method" AS VARCHAR) AS "extraction_method",CAST("aggregation_method" AS VARCHAR) AS "aggregation_method",CAST("contributing_value_count" AS INTEGER) AS "contributing_value_count",CAST("coverage_fraction" AS DOUBLE) AS "coverage_fraction",CAST("distance_to_source_m" AS DOUBLE) AS "distance_to_source_m",CAST("lag_days_applied" AS INTEGER) AS "lag_days_applied",CAST("temporal_grouping" AS VARCHAR) AS "temporal_grouping",CAST("output_column_name" AS VARCHAR) AS "output_column_name",CAST("id" AS VARCHAR) AS "id",CAST("product_variable" AS VARCHAR) AS "product_variable",CAST("canonical_variable" AS VARCHAR) AS "canonical_variable",CAST("asset" AS VARCHAR) AS "asset",CAST("processing_run" AS VARCHAR) AS "processing_run",CAST("value" AS DOUBLE) AS "value",CAST("value_unit_ucum" AS VARCHAR) AS "value_unit_ucum",CAST("native_value" AS DOUBLE) AS "native_value",CAST("native_value_unit_ucum" AS VARCHAR) AS "native_value_unit_ucum",CAST("valid_time_start" AS TIMESTAMP) AS "valid_time_start",CAST("valid_time_end" AS TIMESTAMP) AS "valid_time_end",CAST("reference_time" AS TIMESTAMP) AS "reference_time",CAST("retrieval_time_utc" AS TIMESTAMP) AS "retrieval_time_utc",CAST("vertical_level" AS DOUBLE) AS "vertical_level",CAST("vertical_level_unit" AS VARCHAR) AS "vertical_level_unit",CAST("quality_flag" AS VARCHAR) AS "quality_flag",CAST("data_status" AS VARCHAR) AS "data_status",CAST("source_system" AS VARCHAR) AS "source_system",CAST("source_version" AS VARCHAR) AS "source_version",CAST("null_semantics" AS VARCHAR) AS "null_semantics",CAST("superseded_by" AS VARCHAR) AS "superseded_by" FROM ambient_values_at_location
